package join

import (
	"fmt"
	"sort"
	"strings"
)

// The first renderer that WRITES: the dns records. It makes the dns helper's record file equal to what the join renders, and nothing else.
//
// The layout it relies on (docs/join.md, and measured in a lab against CoreDNS 1.14.7):
//
//   - /hosts on the dns helper is the GENERATED file and holds nothing else. CoreDNS's `hosts` plugin answers from it first and re-reads it every few seconds, so a
//     change needs no restart. The plugin may be used only once per server block (CoreDNS refuses to start otherwise), which is why the generated records cannot sit
//     in a second file beside hand-written ones.
//   - /db.<zone> is the zone file, written by hand, and holds the platform's OWN static names (the sign-on portal, the directory's UI): `hosts` falls through to it
//     for a name it does not have. An empty /hosts therefore takes down no platform name.
//   - Where a name is in both, /hosts wins. So an app published as `auth` would silently take the portal's name; ApplyDNS refuses a label that is already a record in
//     the zone file.
const (
	DNSRecordsPath = "/hosts"
	generatedNote  = "# Generated by `tink join apply dns` from the publish documents. Do not edit: the next run rewrites this file whole.\n"
)

// DNSZonePath is where the zone file is expected: /db.<zone>, the name the platform's Corefile gives its `file` plugin.
func DNSZonePath(zone string) string { return "/db." + zone }

// DNSFile is the generated file's whole content: a note and one record per published name.
func (r Result) DNSFile() string { return generatedNote + r.DNS }

// Files is the slice of an instance's file API the appliers use.
type Files interface {
	// Read returns a file's content. found is false only when the file does not exist: any other failure is an error, never "not found", because a failed read
	// taken for an empty file would let the applier rewrite everything.
	Read(project, instance, path string) (content string, found bool, err error)
	// Write replaces a file's content whole.
	Write(project, instance, path, content string) error
}

// ApplyOptions are the two ways to change what an apply is willing to do.
type ApplyOptions struct {
	DryRun     bool // compute and report, write nothing
	AllowEmpty bool // accept a rendering with no published name (it empties the generated file); refused otherwise, because it usually means the wrong files were named
	Adopt      bool // overwrite a file that tink did not write (one without the note at its top); refused otherwise, because it may hold records written by hand
}

// ApplyReport says what an apply found and did.
type ApplyReport struct {
	Project, Instance, Path string
	Created                 bool     // the file did not exist
	Changed                 bool     // the file's content differs from the rendering (always false when Written is false and nothing differs)
	Written                 bool     // the file was written
	Added, Removed          []string // record lines the write adds to, and takes from, the file
}

// ApplyDNS makes the dns helper's generated record file equal to the rendering. It applies nothing when the join has errors, refuses to replace the records
// with none unless asked, refuses a label that is already a static record in the zone file, and checks by reading the file back that the write took.
func ApplyDNS(f Files, res Result, opts ApplyOptions) (ApplyReport, error) {
	rep := ApplyReport{Project: res.DNSProject, Instance: res.DNSInstance, Path: DNSRecordsPath}
	if n := res.Errors(); n > 0 {
		return rep, fmt.Errorf("the join has %d error(s): nothing was applied", n)
	}
	if res.DNSInstance == "" {
		return rep, fmt.Errorf("no dns helper was found (no instance has %s: dns): nothing to apply to", roleKey)
	}
	if len(res.Published) == 0 && !opts.AllowEmpty {
		return rep, fmt.Errorf("no published name was found, so applying would replace every generated record with none; with files that usually means the wrong files were given, and from the server that nothing is stamped on it yet (--allow-empty says it is meant)")
	}
	if res.Zone == "" {
		return rep, fmt.Errorf("the dns helper states no zone (%s), so the zone file cannot be checked for names it already holds", zoneKey)
	}

	// Refuse a label the platform already owns.
	zonePath := DNSZonePath(res.Zone)
	zone, found, err := f.Read(res.DNSProject, res.DNSInstance, zonePath)
	if err != nil {
		return rep, fmt.Errorf("reading %s on %s: %w", zonePath, res.DNSInstance, err)
	}
	if !found {
		return rep, fmt.Errorf("%s does not exist on %s: the dns helper is not laid out the way the join expects (docs/join.md), so it cannot check the published names against the platform's own", zonePath, res.DNSInstance)
	}
	owners := ZoneOwners(zone, res.Zone)
	var clash []string
	for _, p := range res.Published {
		if owners[p.Label] {
			clash = append(clash, p.Label)
		}
	}
	if len(clash) > 0 {
		return rep, fmt.Errorf("%s already holds a record for %s, and a generated record would answer first and take the name over: rename the publish", zonePath, strings.Join(clash, ", "))
	}

	desired := res.DNSFile()
	current, exists, err := f.Read(res.DNSProject, res.DNSInstance, DNSRecordsPath)
	if err != nil {
		return rep, fmt.Errorf("reading %s on %s: %w", DNSRecordsPath, res.DNSInstance, err)
	}
	if exists && !strings.HasPrefix(current, generatedNote) && !opts.Adopt {
		return rep, fmt.Errorf("%s on %s was not written by tink (it does not begin with the note the join writes), and it holds %d record(s) that applying would remove: move them to the zone file %s if they are the platform's own, then give --adopt once", DNSRecordsPath, res.DNSInstance, len(records(current)), zonePath)
	}
	rep.Created = !exists
	rep.Changed = !exists || current != desired
	rep.Added, rep.Removed = recordDiff(current, desired)
	if !rep.Changed || opts.DryRun {
		return rep, nil
	}
	if err := f.Write(res.DNSProject, res.DNSInstance, DNSRecordsPath, desired); err != nil {
		return rep, fmt.Errorf("writing %s on %s: %w", DNSRecordsPath, res.DNSInstance, err)
	}
	back, ok, err := f.Read(res.DNSProject, res.DNSInstance, DNSRecordsPath)
	if err != nil {
		return rep, fmt.Errorf("the write succeeded but reading %s back failed: %w", DNSRecordsPath, err)
	}
	if !ok || back != desired {
		return rep, fmt.Errorf("the write succeeded but %s on %s does not hold what was written", DNSRecordsPath, res.DNSInstance)
	}
	rep.Written = true
	return rep, nil
}

// records are the lines of a hosts file that are records: not blank, not a comment.
func records(content string) []string {
	var out []string
	for _, l := range strings.Split(content, "\n") {
		if l = strings.TrimSpace(l); l != "" && !strings.HasPrefix(l, "#") {
			out = append(out, l)
		}
	}
	return out
}

// recordDiff is the record lines only in desired, and only in current, each sorted.
func recordDiff(current, desired string) (added, removed []string) {
	cur, want := map[string]bool{}, map[string]bool{}
	for _, l := range records(current) {
		cur[l] = true
	}
	for _, l := range records(desired) {
		want[l] = true
		if !cur[l] {
			added = append(added, l)
		}
	}
	for l := range cur {
		if !want[l] {
			removed = append(removed, l)
		}
	}
	sort.Strings(added)
	sort.Strings(removed)
	return added, removed
}

// ZoneOwners returns the relative owner names in a zone file that has records: "auth" for a line `auth IN A ...` or `auth.<zone>. IN A ...`. A line that
// starts with white space continues the previous record; `$` lines are directives; `;` starts a comment. "@" is the zone itself.
func ZoneOwners(zone, name string) map[string]bool {
	owners := map[string]bool{}
	for _, l := range strings.Split(zone, "\n") {
		if i := strings.Index(l, ";"); i >= 0 {
			l = l[:i]
		}
		if l == "" || l[0] == ' ' || l[0] == '\t' || l[0] == '$' {
			continue
		}
		owner := strings.Fields(l)[0]
		owner = strings.TrimSuffix(strings.TrimSuffix(strings.ToLower(owner), "."+name+"."), ".")
		owners[owner] = true
	}
	return owners
}
